function EXTRA(R,ICON){
 /* hook: a hum (200 rad/s) and a whistle (2000 rad/s) through the RC low-pass of the examples (RC = 1 ms); gains and lags computed from H(ω) */
 const win=0.0314,hum=200,wh=2000;
 const box=(x,y,col,t,inner)=>`<g transform="translate(${x-190} ${y-80})">${FQ_box(0,0,380,160,{fill:'#FFFFFF',st:col,sw:3,r:18})}${FQ_T(20,34,t,{fs:24,fw:800,fill:col})}${inner}</g>`;
 ICON.fqIn=(x,y)=>box(x,y,BLU,'in: equal hum and whistle',FQ_curve(t=>Math.cos(hum*t),0,win,24,356,78,20,BLU,4,200)+FQ_curve(t=>Math.cos(wh*t),0,win,24,356,128,20,ORG,3,400));
 ICON.fqOut=(x,y)=>box(x,y,GRN,'out: whistle smaller, later',FQ_curve(t=>FQ_Hm(hum)*Math.cos(hum*t+FQ_Hp(hum)),0,win,24,356,78,20,BLU,4,200)+FQ_curve(t=>FQ_Hm(wh)*Math.cos(wh*t+FQ_Hp(wh)),0,win,24,356,128,20,ORG,3,400));
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.fqMod=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${FQ_L(10,270,410,270,FQ_AX,2)}${FQ_curve(w=>FQ_G(w)*2,-20,20,10,410,270,220,FQ_GREY,3,200,'stroke-dasharray="7 6"')}${FQ_curve(w=>FQ_Xmod(w)*2,-20,20,10,410,270,220,BLU,5,240)}${FQ_T(110,310,'−ω₀',{fs:26,fw:800,a:'middle',fill:BLU})}${FQ_T(310,310,'+ω₀',{fs:26,fw:800,a:'middle',fill:BLU})}${FQ_T(210,30,'two half copies',{fs:26,fw:800,a:'middle',fill:BLU})}</g>`;
 ICON.fqPars=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${FQ_L(0,250,180,250,FQ_AX,2)}${FQ_area(t=>Math.exp(-6*t),0,1,6,180,250,170,BLU,.3)}${FQ_curve(t=>Math.exp(-6*t),0,1,6,180,250,170,BLU,5)}${FQ_T(200,180,'=',{fs:50,fw:800,a:'middle'})}${FQ_L(230,250,420,250,FQ_AX,2)}${FQ_area(w=>9*FQ_esd(w),-12,12,230,420,250,170,ORG,.3)}${FQ_curve(w=>9*FQ_esd(w),-12,12,230,420,250,170,ORG,5)}${FQ_T(90,300,'in time',{fs:26,fw:800,a:'middle',fill:BLU})}${FQ_T(325,300,'÷ 2π',{fs:26,fw:800,a:'middle',fill:ORG})}${FQ_T(210,30,'1/6 J both ways',{fs:26,fw:800,a:'middle'})}</g>`;
 ICON.fqLow=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${FQ_L(20,270,410,270,FQ_AX,2)}${FQ_L(20,40,20,270,FQ_AX,2)}${FQ_curve(w=>FQ_Hm(w),0,5000,20,410,270,220,GRN,5)}<circle cx="${20+390*0.2}" cy="${(270-220*FQ_Hm(1000)).toFixed(1)}" r="9" fill="${GRN}"/><circle cx="${20+390*0.4}" cy="${(270-220*FQ_Hm(2000)).toFixed(1)}" r="9" fill="${GRN}"/>${FQ_T(118,112,'0.707',{fs:24,fw:800,fill:GRN})}${FQ_T(196,162,'0.447',{fs:24,fw:800,fill:GRN})}${FQ_T(410,306,'ω (rad/s)',{fs:22,a:'end',fill:FQ_GREY})}${FQ_T(30,30,'|H(ω)|',{fs:24,fw:800,fill:GRN})}</g>`;
}
